--- a/sistema/sistema.cpp
+++ b/sistema/sistema.cpp
@@ -2008,26 +2008,25 @@ bool handle_watch_pf(vaddr cr2)
 	watch_des *w = &watch_state;

 	if (!w->v) {
-		// non ci sono watch attivi
 		return false;
 	}

 	if (base(cr2, 0) != base(w->v, 0)) {
-		// l'accesso non riguarda il watch corrente
 		return false;
 	}

-	// permettiamo al processo di eseguire la scrittura e lo catturiamo subito dopo
-	natq *pila =  ptr_cast<natq>(esecuzione->contesto[I_RSP]);
-	pila[2] |= BIT_TF;
-	pila[2] &= ~BIT_IF;
 	tab_iter it(esecuzione->cr3, w->v, w->size);
 	while (it.down())
 		;
 	it.get_e() |= BIT_RW;
-	// siccome stiamo attivando la scrittura che prima era disabilitata, il
-	// TLB causerà sicuramente miss sull'operazione in scrittura e dunque
-	// non c'è bisogno di invalidare l'entrata
+
+	if (esecuzione->id == w->watcher_id) {
+		return true;
+	}
+
+	natq *pila =  ptr_cast<natq>(esecuzione->contesto[I_RSP]);
+	pila[2] |= BIT_TF;
+	pila[2] &= ~BIT_IF;

 	esecuzione->being_watched = true;

@@ -2044,9 +2043,41 @@ bool handle_watch_pf(vaddr cr2)
  */
 bool handle_watch_ss()
 {
-/// @todo Gestire l'evento
-// ( SOLUZIONE 2024-06-07
-//   SOLUZIONE 2024-06-07 )
+	watch_des *w = &watch_state;
+
+	if (!w->v) {
+		return false;
+	}
+
+	if (!esecuzione->being_watched) {
+		return false;
+	}
+
+	natq new_value = 0;
+	memcpy(&new_value, voidptr_cast(w->v), w->size);
+
+	if (new_value != w->old_value) {
+		esecuzione->new_watch_value = new_value;
+		if (esecuzione->id != w->watcher_id) {
+			w->old_value = new_value;
+			inserimento_in_fondo(w->watched_waiting, esecuzione);
+			esecuzione->being_watched = false;
+			des_proc *w_wait = rimozione_lista(w->watcher_waiting);
+			if (w_wait) {
+				inserimento_lista(pronti, w_wait);
+			}
+		}
+	}
+
+	tab_iter it(esecuzione->cr3, w->v, w->size);
+	while (it.down())
+		;
+	it.get_e() &= ~BIT_RW;
+	natq *pila = ptr_cast<natq>(esecuzione->contesto[I_RSP]);
+	pila[2] &= ~BIT_TF;
+	pila[2] |= BIT_IF;
+
+	return true;
 }

 /**
@@ -2054,9 +2085,36 @@ bool handle_watch_ss()
  */
 extern "C" void c_watch()
 {
-/// @todo Realizzare la primitiva
-// ( SOLUZIONE 2024-06-07
-//   SOLUZIONE 2024-06-07 )
+	watch_des *w = &watch_state;
+
+	if (!w->v) {
+		c_abort_p();
+		return;
+	}
+
+	if (esecuzione->id != w->watcher_id) {
+		c_abort_p();
+		return;
+	}
+
+	des_proc *watcher = esecuzione;
+
+	while (!w->watched_waiting) {
+		inserimento_in_fondo(w->watcher_waiting, watcher);
+		watcher->puntatore = nullptr;
+		schedulatore();
+	}
+
+	des_proc *watched = rimozione_lista(w->watched_waiting);
+	if (watched) {
+		inserimento_lista(pronti, watched);
+	}
+
+	natq value = watcher->new_watch_value;
+	natq mask = (1ULL << (w->size * 8)) - 1;
+	value &= mask;
+
+	watcher->contesto[I_RAX] = value;
 }
 //   ESAME 2024-06-07 )
 /// @}
diff --git a/sistema/sistema.s b/sistema/sistema.s
index 2c88781..8136ce8 100644
--- a/sistema/sistema.s
+++ b/sistema/sistema.s
@@ -1471,5 +1471,15 @@ exc_error:
 .global tss_punt_nucleo
 tss_punt_nucleo:
 	.quad 0
+
+/// @brief Legge il registro CR2 (contiene l'indirizzo del page fault)
+/// @return valore di CR2 in RAX
+	.global readCR2
+readCR2:
+	.cfi_startproc
+	.cfi_def_cfa_offset 8
+	movq %cr2, %rax
+	ret
+	.cfi_endproc
 /// @endcond
 /// @}
